import { create } from 'zustand';
import { persist } from 'zustand/middleware';

const useCartStore = create(persist(
  (set, get) => ({
    items: [],

    addItem: (product) => {
      const existing = get().items.find(i => i._id === product._id);
      if (existing) {
        set(state => ({
          items: state.items.map(i =>
            i._id === product._id ? { ...i, quantity: i.quantity + 1 } : i
          )
        }));
      } else {
        set(state => ({ items: [...state.items, { ...product, quantity: 1 }] }));
      }
    },

    removeItem: (productId) => set(state => ({
      items: state.items.filter(i => i._id !== productId)
    })),

    clearCart: () => set({ items: [] }),

    // Computed values
    get totalItems() { return get().items.reduce((sum, i) => sum + i.quantity, 0); },
    get totalPrice() { return get().items.reduce((sum, i) => sum + i.price * i.quantity, 0); },
  }),
  { name: 'cart-storage' }  // Persists to localStorage
));

export default useCartStore;

